segments=[(-7,7,15),(-3,5,13),(2,4,9),(7,3,4)]
def hull_poly(points):
    pts=sorted(set(points))  # (c,r)
    # monotonic convex hull
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in pts:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    up=[]
    for p in reversed(pts):
        while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
        up.append(p)
    return lo[:-1]+up[:-1]
def pip(x,y,poly):
    # inclusive polygon: ray casting plus on edge
    inside=False
    for i,(x1,y1) in enumerate(poly):
        x2,y2=poly[(i+1)%len(poly)]
        cr=(x-x1)*(y2-y1)-(y-y1)*(x2-x1)
        if abs(cr)<1e-9 and min(x1,x2)-1e-9<=x<=max(x1,x2)+1e-9 and min(y1,y2)-1e-9<=y<=max(y1,y2)+1e-9: return True
        if (y1>y)!=(y2>y):
            xx=x1+(y-y1)*(x2-x1)/(y2-y1)
            if x < xx: inside=not inside
    return inside
